const dbResult = $('1. Validar Token e Buscar Raiz').first();
const rootId = dbResult && dbResult.json ? dbResult.json.id_pasta_raiz : null;
const clienteId = dbResult && dbResult.json ? dbResult.json.cliente_id : null;

if (!clienteId || !rootId) {
  throw new Error("Sessão inválida ou Cliente sem Pasta Raiz configurada.");
}

const area = $('Receber Arquivo (POST)').first().json.body.area || '';
let folderName = '99_DIVERSOS';
const areaLower = area.toLowerCase();

if (areaLower.includes('fiscal')) folderName = '01_FISCAL';
else if (areaLower.includes('pessoal') || areaLower.includes('rh') || areaLower.includes('dp')) folderName = '02_PESSOAL';
else if (areaLower.includes('contabil') || areaLower.includes('contábil')) folderName = '03_CONTABIL';
else if (areaLower.includes('societario') || areaLower.includes('societário')) folderName = '04_SOCIETARIO';
else if (areaLower.includes('inbox')) folderName = '00_INBOX';

return [{ json: { targetFolder: folderName, rootId: rootId, cliente_id: clienteId } }];

const pasta = $input.first().json;
const webhookItem = $('Receber Arquivo (POST)').first();
const routeItem = $('2. Roteador de Área (JS)').first().json;
const body = webhookItem.json.body ?? {};
// Observação opcional do cliente; o nome do campo no formulário não foi confirmado, por isso aceita as variantes conhecidas.
const rawObs = body.observacao ?? body.observacao_cliente ?? body.observacoes ?? '';
const observacao = String(rawObs).trim().slice(0, 2000) || null;
const rawComp = String(body.competencia ?? '').trim();
const competencia = /^(0[1-9]|1[0-2])\/\d{4}$/.test(rawComp) ? rawComp : null;
const binaryKeys = webhookItem.binary ? Object.keys(webhookItem.binary) : [];

if (!binaryKeys.length) throw new Error('Nenhum arquivo binário encontrado');

return [{
  json: {
    ...pasta,
    cliente_id: routeItem.cliente_id,
    area: webhookItem.json.body?.area ?? null,
    titulo: webhookItem.json.body?.titulo ?? webhookItem.json.body?.nome_arquivo ?? 'arquivo_sem_nome',
    observacao_cliente: observacao,
    competencia,
    binary_field_name: binaryKeys[0]
  },
  binary: webhookItem.binary
}];

const item = $input.first();
const jsonBase = item.json || {};
const binaries = item.binary || {};
const output = [];
for (const [key, file] of Object.entries(binaries)) {
  output.push({
    json: { ...jsonBase, binary_source_field: key, nome_arquivo_original: file.fileName || null, mime_type: file.mimeType || null },
    binary: { data: file }
  });
}
return output;

const headers = $input.first().json.headers || {};
const auth = headers.authorization || headers.Authorization || '';
// Mantém só letras e números: impede qualquer caractere de quebrar o SQL da validação.
const token = auth.replace(/^Bearer\s+/i, '').replace(/[^a-zA-Z0-9]/g, '');
return [{ json: { token } }];
